use kimo_core::{color::film_response as r,effects::{Frame,Params},keyframe::Prop};
#[test]fn curve_known_monotone_and_precision(){let mut prev=-1f64;let mut max=0f64;for i in 0..100001{let x=i as f64/10000.;let y=r::shoulder(x,0.75,1.);assert!(y>=prev&&y<=1.);prev=y;let mut f=Frame{w:1,h:1,d:vec![x as f32,x as f32,x as f32,1.]};r::apply("film_soft_shoulder",&Params::new(),&mut f,0.,0).unwrap();max=max.max((f.d[0] as f64-r::shoulder(x as f32 as f64,0.75,1.)).abs());}assert!((r::shoulder(1.,0.75,1.)-0.908030139707).abs()<1e-12);assert!((r::shoulder(2.,0.75,1.)-0.99831551325).abs()<1e-11);assert!(max<3e-8);println!("shoulder f32 quantization max {max}");}
#[test]fn grain_density_statistics_determinism(){let mut counts=Vec::new();for l in [0.05,0.5,0.95]{let f=Frame{w:512,h:512,d:(0..512*512).flat_map(|_|[l,l,l,1.]).collect()};let mut a=Frame{w:f.w,h:f.h,d:f.d.clone()};let mut b=Frame{w:f.w,h:f.h,d:f.d.clone()};r::apply("film_luma_grain",&Params::new(),&mut a,0.,42).unwrap();r::apply("film_luma_grain",&Params::new(),&mut b,0.,42).unwrap();assert_eq!(a.d,b.d);let occupancy=a.d.chunks_exact(4).filter(|c|c[0]!=l).count() as f64/(512.*512.);let expected=r::density(l as f64,0.9f32 as f64,0.08f32 as f64,1.5);assert!((occupancy-expected).abs()<0.004);let mean=a.d.chunks_exact(4).map(|c|c[0] as f64-l as f64).sum::<f64>()/(512.*512.);assert!(mean.abs()<0.0001);println!("luma {l} occupancy{occupancy} expected{expected} mean{mean}");counts.push(occupancy);}assert!(counts[0]>counts[1]&&counts[1]>counts[2]);}
#[test]fn no_op_alpha_negative_and_hostile(){for k in ["film_soft_shoulder","film_luma_grain"]{let mut f=Frame{w:2,h:1,d:vec![-0.3,2.,0.8,0.,-0.3,2.,0.8,0.4]};let original=f.d.clone();let mut p=Params::new();p.insert("amount".into(),Prop::new(0.));r::apply(k,&p,&mut f,0.,42).unwrap();assert_eq!(f.d,original);r::apply(k,&Params::new(),&mut f,0.,42).unwrap();assert_eq!(f.d[..4],original[..4]);assert_eq!(f.d[7],0.4);p.insert("amount".into(),Prop::new(f64::NAN));assert!(r::apply(k,&p,&mut f,0.,42).is_err());}}
#[test]fn mcp_catalog_response(){use kimo_core::commands::{Session,dispatch};let mut s=Session::new();assert!(dispatch(&mut s,"inspect_film_response",&serde_json::json!({})).unwrap()["shoulder"].is_array());}
#[cfg(feature="native-ocio")]
#[test]fn native_domain_reference(){use kimo_core::color::{ocio_config::Config,effect_domain::{DomainProcessor,WorkingDomain}};let c=Config::from_text(include_str!("data/minimal_aces.ocio")).unwrap();let d=DomainProcessor::new(&c,"ACEScg","ACEScg","DisplayGamma2",WorkingDomain::DisplayReferred).unwrap();let mut f=Frame{w:1,h:1,d:vec![1.21,0.25,0.04,1.]};d.apply("film_soft_shoulder",&Params::new(),&std::collections::BTreeMap::new(),&mut f,0.,42).unwrap();let expected=r::shoulder(1.21f32.sqrt() as f64,0.75,1.).powi(2);assert!((f.d[0] as f64-expected).abs()<2e-6);assert!((f.d[1]-0.25).abs()<1e-6);let mut f=Frame{w:128,h:64,d:(0..8192).flat_map(|_|[0.04,0.25,0.81,1.]).collect()};let mut g=Frame{w:f.w,h:f.h,d:f.d.clone()};d.apply("film_luma_grain",&Params::new(),&std::collections::BTreeMap::new(),&mut f,0.,42).unwrap();c.processor("ACEScg","DisplayGamma2").unwrap().apply(&mut g).unwrap();r::apply("film_luma_grain",&Params::new(),&mut g,0.,42).unwrap();c.processor("DisplayGamma2","ACEScg").unwrap().apply(&mut g).unwrap();assert_eq!(f.d,g.d);}
#[cfg(feature="native-ocio")]
#[test]fn real_native_view_proof(){let Ok(path)=std::env::var("KIMO_TEST_NATIVE_ACES_CONFIG")else{return};if !std::path::Path::new("/tmp/view-real-timeline-input.f32").exists(){return}use kimo_core::color::ocio_config::Config;let bytes=std::fs::read("/tmp/view-real-timeline-input.f32").unwrap();let input:Vec<f32>=bytes.chunks_exact(4).map(|v|f32::from_le_bytes(v.try_into().unwrap())).collect();let c=Config::from_file(path).unwrap();let proc=c.display_processor("ACEScg","sRGB - Display","ACES 2.0 - SDR 100 nits (Rec.709)").unwrap();let mut f=Frame{w:640,h:360,d:input};proc.apply(&mut f).unwrap();let save=|path:&str,f:&Frame|std::fs::write(path,f.d.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).unwrap();save("/tmp/film-tone-view-before.f32",&f);r::apply("film_soft_shoulder",&Params::new(),&mut f,0.,42).unwrap();save("/tmp/film-tone-shoulder.f32",&f);r::apply("film_luma_grain",&Params::new(),&mut f,0.,42).unwrap();save("/tmp/film-tone-after.f32",&f);}
#[test]fn add_effect_native_strings_and_grain_bounds(){use kimo_core::commands::{Session,dispatch};use serde_json::json;let mut s=Session::new();let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":t,"source_type":"solid","color":[0.2,0.3,0.4],"start":0,"duration":1})).unwrap()["clip_id"].clone();for kind in ["film_soft_shoulder","film_luma_grain"]{dispatch(&mut s,"add_effect",&json!({"clip_id":c,"kind":kind,"params":{"amount":0.1},"strings":{"ocio_domain":"display-referred","ocio_config":concat!(env!("CARGO_MANIFEST_DIR"),"/tests/data/minimal_aces.ocio"),"ocio_working_space":"ACEScg","ocio_linear_space":"ACEScg","ocio_display_space":"DisplayGamma2"}})).unwrap();}let mut f=Frame{w:512,h:512,d:(0..262144).flat_map(|i|{let v=-4.+8.*i as f32/262144.;[v,v,v,1.]}).collect()};let before=f.d.clone();r::apply("film_luma_grain",&Params::new(),&mut f,0.,42).unwrap();for(a,b)in before.iter().zip(&f.d){assert!((*a as f64-*b as f64).abs()<=0.0250003);}}
